with d as (select value r from jsonb_array_elements($q$[{"notes":["Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"id":"139e1906-6272-436a-824b-643654998519"},{"steps":[{"text":"Preheat your camp oven with coals underneath and on top, or preheat a conventional oven to 200°C."},{"text":"In a large bowl, mix together the flour, baking powder, wattleseed and salt."},{"text":"Add the cubed butter and rub it in with your fingertips until the mixture resembles fine breadcrumbs."},{"text":"Add the warm water gradually, stirring with a knife until the dough just comes together. Don't overwork it, damper should be rough and rustic."},{"text":"Turn the dough out onto a lightly floured surface and gently shape it into a round loaf about 20 cm across. Make a shallow cross on the top with a knife."},{"text":"Place the damper on a piece of baking paper or directly on a lightly oiled cast-iron trivet in your camp oven (or on a baking tray for conventional oven)."},{"text":"Bake for 40–45 minutes until the top is golden and it sounds hollow when tapped on the base. In a camp oven, rotate the coals if needed to ensure even cooking."},{"text":"Cool on a wire rack for a few minutes, then tear into pieces and serve warm with butter."}],"id":"2b330fc3-079d-4416-ae94-2f7d1d6be214"},{"notes":["Cook the rice the night before and store in the fridge; it keeps for 3 days and is great eaten cold.","Press the tofu for 15 minutes before cutting to get it crispy, wrap it in a clean towel with a weight on top.","Swap the mango for peaches or papaya if that's what's at the farmers' market."],"id":"5fff3577-9796-44bc-9f11-a72774be05f3"},{"notes":["Make the stew up to 2 days ahead; the flavours deepen overnight. Reheat gently before serving.","Don't skip browning the kidney, it anchors the stew. If you can't find beef kidney, use lamb kidney (200 g) or omit it and add 100 g more beans instead.","Dried limes are essential to the flavour; they're sold in Middle Eastern grocers and most good supermarkets.","Food safety: Steaks and roasting cuts of beef or lamb can be served pink: about 60°C in the centre is medium-rare, 70°C is well done. If using dried kidney beans, soak them, then boil them hard for at least 10 minutes before simmering, to destroy a natural toxin."],"id":"eeebbc70-230c-470a-9de2-16fa75d8bd13"},{"notes":["Use oil you actually like the taste of, the simplicity means quality matters. Peanut oil or a fruity olive oil both work.","Don't prep the choy sum too early; it wilts quickly. Cut and dress it just before cooking.","If your stove doesn't run hot enough to get good wok hei, finish the pan under a very hot grill for 30 seconds instead."],"steps":[{"text":"Get everything ready, the greens washed and cut, garlic bruised and sitting on the bench. High heat and speed matter here."},{"text":"Heat your wok on high until it just begins to smoke lightly, about 2 minutes. Add the oil and swirl to coat the wok surface."},{"text":"Add the bruised garlic and stir constantly for 20 seconds until fragrant. You want the oil infused but the garlic not burnt."},{"text":"Immediately add all the choy sum. Toss and stir briskly, keeping the heat high, for 2 to 3 minutes until the stems are tender and the leaves have some char at the edges. The greens should still be bright."},{"text":"Season with salt to taste. Serve immediately while the oil is still hot and the choy sum is at its best."}],"id":"51a02573-191b-47fa-a577-ae68ab84ae77"},{"notes":["The salmon can be cured up to 5 days ahead; keep it wrapped in the fridge. Slice only what you need and use the rest within a day or two.","The mustard sauce keeps refrigerated for up to 3 days.","Use the best salmon you can find, it's almost raw, so freshness matters.","The fish here is eaten raw or only cured in citrus. Buy sashimi-grade fish from a fishmonger, keep it cold and eat it the same day; skip it for anyone pregnant, very young, elderly or with low immunity.","Food safety: The seafood here is served raw or cured, so buy sashimi-grade, keep it cold and eat it the day it is made; for anyone who should avoid raw fish, cook it until opaque. Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"cf8f997a-6288-41b8-bc77-476798a51267"},{"notes":["If you can't find fresh pāua, tinned pāua from a specialist kai moana supplier works well, just drain and pound before battering.","Keep finished fritters warm in a low oven (120°C) while you fry the rest.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Pound each pāua gently but firmly with a meat mallet on both sides until soft and just starting to flatten. Don't overdo it or you'll tear them. Pat dry with paper towels."},{"text":"Whisk together the flour, baking powder, salt and pepper in a large bowl. In another bowl, whisk the egg with the milk until combined."},{"text":"Pour the wet ingredients into the dry and stir gently until just combined, the batter should be a little lumpy, not smooth."},{"text":"Heat about 2 cm of neutral oil in a large frying pan over medium-high heat until shimmering. Test with a drop of batter; it should sizzle and float."},{"text":"Dip each pāua into the batter, coating both sides, then carefully place into the hot oil. Fry in batches of 2 or 3 so you don't crowd the pan, about 2 minutes each side until golden and crispy."},{"text":"Drain on paper towels and serve hot with a squeeze of fresh lemon."}],"id":"0d54dff1-13b6-4206-8cf0-96ea38ee1cb0"},{"notes":["Make ahead: prepare the musubi the morning before and keep wrapped in the fridge. Bring to room temperature before eating, or warm gently in the microwave.","Swap the sweet soy sauce for tamari or regular soy sauce if that's what you've got, the musubi will taste less sweet but still good.","Any leftover seasoned rice can be used to make onigiri or fried rice.","Food safety: Cool any leftover rice quickly and refrigerate it within an hour; reheat it until steaming hot."],"id":"f6d16acd-ceca-43e3-9aad-e122c444b178"},{"notes":["Use veal or beef. Veal is more tender, but a thin beef cutlet works just as well.","Don't skip the meat mallet. The escalopes must be thin so they cook through before the breadcrumb coating burns.","Food safety: Steaks and roasting cuts of beef or lamb can be served pink: about 60°C in the centre is medium-rare, 70°C is well done."],"steps":[{"text":"Make the chimichurri first: whisk together the olive oil and red wine vinegar, then stir in the parsley, oregano, garlic, chilli flakes, salt and pepper. Set aside."},{"text":"Place each veal escalope between two sheets of plastic wrap and pound with a meat mallet or rolling pin until very thin, about 3 mm. Season both sides with salt and pepper."},{"text":"Set up three shallow bowls: one with flour, one with beaten eggs, and one with breadcrumbs. Coat each escalope in flour, shaking off excess, then dip in egg, then press firmly into the breadcrumbs on both sides."},{"text":"Heat about 1 cm of neutral oil in a large frying pan over medium-high heat until it shimmers. Test with a small piece of bread, it should sizzle and brown quickly."},{"text":"Carefully lay the breaded veal into the hot oil and fry for 2–3 minutes until golden brown. Turn and fry the other side for another 2–3 minutes until crispy and golden. Do not overcrowd the pan."},{"text":"Transfer to a plate lined with paper towel to drain. Serve hot with lemon wedges and chimichurri on the side, with optional fresh parsley garnish."}],"id":"b810c302-8b19-48c5-884f-f620802c7e5b"},{"notes":["The yolk should be soft when you bite in, if you prefer it cooked through, fry for an extra minute, but you'll lose some of the magic!","If the pastry is splitting, brush the edges with a paste of flour and water to seal them better.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Set up a work station with one sheet of filo pastry in front of you, and have a small bowl of water nearby for sealing. In a small bowl, mix the drained tuna with the harissa, coriander and capers. Taste it and adjust the harissa and salt to your liking."},{"text":"Take the first filo sheet and brush it lightly with oil on both sides. Fold it in half to create a rough square."},{"text":"Spoon about 1 tbsp of the tuna mixture into the centre of the folded pastry, leaving a margin around the edges. Make a small well in the tuna mixture, then crack an egg directly into it. Season with a pinch of salt and pepper."},{"text":"Fold the pastry over the filling to create a triangle or envelope, sealing the edges by pressing firmly or brushing them with a little water. The egg should be mostly contained but might leak slightly during cooking, this is normal."},{"text":"Heat about 3 cm of oil in a deep frying pan to 180°C (or until a small piece of bread browns in about 30 seconds). Carefully place the first brik into the hot oil, seam-side down."},{"text":"Fry for 2–3 minutes, turning once halfway, until the pastry is golden and crispy on both sides. The egg inside should still have a soft yolk. Use a slotted spoon to remove it and drain on paper towels."},{"text":"Repeat with the remaining briks, making sure the oil returns to temperature between batches."},{"text":"Serve hot, on their own or with a squeeze of lemon and extra harissa on the side!"}],"id":"dbe35766-9aeb-45a4-bd02-b1981219f0bd"},{"notes":["Shorshe ilish is traditionally made during spring when hilsa is in season (March–May). If hilsa is unavailable, use fresh pomfret or mackerel, both have the oily texture this dish demands.","Prepare the mustard paste fresh; it loses its pungency if made too far ahead. The dish can be made a few hours in advance and gently reheated."],"steps":[{"text":"Soak the mustard seeds in a little water for 10 minutes, then grind to a coarse paste with the green chillies, turmeric and salt. The paste should be lumpy and pungent, not smooth."},{"text":"Heat the mustard oil in a wide, shallow pan over medium-high heat until it just smokes, about 2 minutes. This is essential, the burnt edge of the oil gives shorshe ilish its character."},{"text":"Gently lay the fish fillets skin-side up in the hot oil. Cook for 2–3 minutes without moving them, until the flesh begins to turn opaque at the edges."},{"text":"Spread the mustard paste over the fish, then add 150 ml water around (not over) it. The sauce should be loose and gravy-like."},{"text":"Bring to a simmer, then reduce heat to low. Cook, uncovered and barely disturbing the fish, for 15–18 minutes, until the flesh is cooked through and flakes easily when tested at its thickest point. The sauce should reduce and thicken slightly."},{"text":"Taste and adjust salt. Stir in the jaggery if using, a hint of sweetness balances the mustard's heat. Serve hot, with rice to soak up the sauce."}],"id":"06d61d99-cdd2-48fe-84ff-da51bdbe66e0"},{"notes":["Rendang improves overnight as the flavours marry. Make it a day ahead and gently reheat, or store in the fridge for up to 4 days.","Use a heavy-bottomed pot so the heat stays even and the sauce doesn't catch at the bottom.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"steps":[{"text":"Blend the garlic, ginger, red chillies, shallots and macadamias with 60 ml of the coconut milk until you have a smooth, thick paste. This is your spice foundation, don't rush it."},{"text":"Heat the oil in a large, heavy-bottomed pot or Dutch oven over medium heat. Add the lemongrass and bruise it gently with a wooden spoon to release its oils, about 1 minute."},{"text":"Add the spice paste and cook, stirring constantly, until it darkens and the raw smell fades, about 8–10 minutes. The paste should start to break apart and release its fragrance."},{"text":"Add the beef chunks and stir well to coat in the paste. Cook for about 5 minutes, stirring occasionally, until the beef is sealed on the outside."},{"text":"Pour in the remaining coconut milk. Stir well, then bring to a gentle simmer, until small bubbles appear at the edges. Do not boil. Reduce the heat to low."},{"text":"Simmer, uncovered, for about 60–70 minutes, stirring every 15 minutes or so. The coconut milk will gradually reduce and the sauce will thicken and darken. By the end, the beef should be very tender and the sauce should be thick and cling to the meat, not swim in liquid. This is where patience matters, watch that the heat stays gentle so the coconut doesn't split."},{"text":"Taste and season with salt. If the rendang feels too sharp, stir in the palm sugar. Remove the lemongrass stalks."},{"text":"The rendang is ready when the sauce is nearly absorbed, glossy and deep reddish-brown, and the beef is so tender it breaks easily with a spoon. Serve warm."}],"id":"6a021a39-3aa2-4e18-97bc-9f2250670ef8"},{"notes":["These are best served warm or at room temperature, not hot, the flavours settle beautifully as they cool.","You can make them a few hours ahead and reheat gently in a 150°C oven for 15 minutes.","If your tomatoes are not very ripe, add a tbsp of tomato paste to the rice mixture for more depth."],"steps":[{"text":"Cut the top off each tomato and set aside. Using a spoon, scoop out the insides, leaving about 1 cm of flesh around the walls. Chop the scooped flesh and set aside. Cut the capsicums in half and remove the seeds."},{"text":"Heat 2 tbsp of the olive oil in a large frying pan over medium heat. Cook the onion until soft, about 5 minutes. Add the garlic and cook for another minute, stirring."},{"text":"Add the rice and stir for 2 minutes to toast it lightly. Add the chopped tomato flesh, parsley, mint, oregano, and a pinch of salt and pepper. Stir well and remove from heat. Let cool slightly."},{"text":"Arrange the tomato shells and capsicum halves in a large baking dish, cut-side up. Divide the rice mixture evenly among them, pressing gently and mounding slightly, they'll settle as they cook until the rice is tender and the tops are lightly golden."},{"text":"Drizzle the remaining 2 tbsp olive oil over everything. Pour the water into the dish around (not over) the vegetables. Replace the tomato tops. Season with salt and pepper."},{"text":"Roast, uncovered, at 180°C for about 60 minutes, until the tomatoes and capsicums are very soft and the edges are slightly charred. The rice will have absorbed most of the liquid. Serve warm or at room temperature."}],"id":"cd5139ba-651e-4292-8e06-f67c887dc10f"},{"notes":["This keeps well in an airtight container in the fridge for up to 5 days, making it perfect for bento prep.","If you can't find burdock, use parsnip cut into thin matchsticks; it cooks a little faster but has a similar sweetness.","Hijiki expands as it soaks, so don't skip that step, the texture will be much better."],"id":"7a434c40-e813-499c-9bc6-28b5e6cca24b"},{"steps":[{"text":"Chop the tomatoes, cucumber and red onion into roughly the same size pieces. Put them in a big bowl."},{"text":"Add the olive oil, lemon juice and oregano. Toss everything together and season with salt and pepper."},{"text":"Let it sit for 2 minutes, until the salt has drawn out a little juice and the vegetables are glossy, so the flavours come together."},{"text":"Scatter the feta on top and toss through gently. Serve straight away."}],"id":"1050cc3f-5e37-4012-a32d-1732d574211b"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;